// This file is generated by AI.

// 项目打开/关闭/创建控制器。

import { readGameConfig } from './commands/gameConfig';
import { copyDirectory } from './commands/server';
import { findBinding } from './lib/bindings';
import { fs } from './lib/fs';
import { gameConfigSummary, parseGameConfigText, setGameConfigValues, type GameConfigSummary } from './lib/gameConfig';
import { joinPath, sanitizeFolderName, stripTrailingSeparator } from './lib/paths';
import { upsertRecentProject } from './lib/recentProjects';
import { loadSession, saveSession, sessionFromTabs } from './lib/session';
import type { EngineEntry, TemplateEntry } from './lib/settings';
import { toUri } from './lib/uri';
import { lspClient } from './lsp/client';
import { disposeModel } from './lsp/monaco';
import { disposeAllNovelTabs } from './novel/registry';
import { previewClient } from './preview/client';
import { useAppStore } from './state/store';
import { makeConfigTab, makeResourceTab, sceneTabId, type ResourceKind } from './tabs/model';
import { voiceController } from './voice/controller';

/** 项目配置文件 (`game/config.txt`) 的绝对路径。 */
export function configPathOf(projectPath: string): string {
  return joinPath(stripTrailingSeparator(projectPath), 'game', 'config.txt');
}

/** 读取并打开一个文件: 登记文档并打开 (或聚焦) 对应选项卡。
 *
 * 已经打开过的文档**一律以内存里那一份为准**, 不再重新读盘: 磁盘上可能是 600ms 之前的
 * 旧内容 (自动保存还没落地), 拿它覆盖文档会顺着"文档 -> 编辑器"的回灌把用户刚敲的字抹掉,
 * 还会往撤销栈里塞一条整档替换 (此后撤回/重做就错位了)。要刷新磁盘内容请用差异页或
 * 场景冲突裁决。
 */
export async function openFile(path: string): Promise<void> {
  const normalized = path.replace(/\\/g, '/');
  const name = normalized.split('/').pop() ?? path;
  const store = useAppStore.getState();
  const opened = store.documents.some((doc) => doc.path === path);

  if (!opened) {
    const content = await fs.readText(path);
    store.openDocument({
      path,
      name,
      uri: toUri(path),
      content,
      dirty: false,
      isScene: normalized.includes('/game/scene/'),
    });
  }

  // 文档与选项卡是两件事: 只登记文档的话界面上不会出现任何选项卡
  store.openSceneTab(path, name);
}

/** 打开资源选项卡: 文本资源进入 Monaco, 媒体资源在工作区显示对应控件。
 *
 * 文本资源同样"已打开就不再读盘", 理由见 `openFile`。
 */
export async function openResourceFile(path: string, resourceKind: ResourceKind): Promise<void> {
  const name = path.replace(/\\/g, '/').split('/').pop() ?? path;
  const store = useAppStore.getState();

  if (resourceKind === 'text' && !store.documents.some((doc) => doc.path === path)) {
    const content = await fs.readText(path);
    store.openDocument({
      path,
      name,
      uri: toUri(path),
      content,
      dirty: false,
      isScene: false,
    });
  }

  store.openTab(makeResourceTab(path, name, resourceKind));
}

/**
 * 在编辑器中打开项目的 `game/config.txt`。
 *
 * 走**配置选项卡**而不是普通资源选项卡: 它是项目的配置而不是一份素材, 选项卡上要带
 * 一个不同的图标 (见 `makeConfigTab`), 从此在标题栏一眼能认出哪条是配置。
 */
export async function openProjectConfig(projectPath: string): Promise<void> {
  const path = configPathOf(projectPath);
  const name = path.replace(/\\/g, '/').split('/').pop() ?? path;
  const store = useAppStore.getState();

  if (!store.documents.some((doc) => doc.path === path)) {
    const content = await fs.readText(path);
    store.openDocument({
      path,
      name,
      uri: toUri(path),
      content,
      dirty: false,
      isScene: false,
    });
  }

  store.openTab(makeConfigTab(path, name));
}

/**
 * 读取项目的游戏配置摘要 (侧栏与最近项目列表用)。
 *
 * **已经打开的 config.txt 以内存里那一份为准**: 它可能正被编辑且尚未存盘, 磁盘上
 * 那份是旧的。解析规则与语言服务一致, 因此两种来源给出的名字/值不会打架。
 */
export async function readProjectConfigSummary(projectPath: string): Promise<GameConfigSummary> {
  const configPath = configPathOf(projectPath);
  const opened = useAppStore
    .getState()
    .documents.find(
      (doc) => doc.path.replace(/\\/g, '/').toLowerCase() === configPath.replace(/\\/g, '/').toLowerCase()
    );

  if (opened) return gameConfigSummary(parseGameConfigText(opened.content));

  try {
    const result = await readGameConfig(projectPath);
    return gameConfigSummary(result.entries);
  } catch {
    // 读不到就当没有配置: 列表仍要能显示 (退回目录名), 不该因为一个坏文件整页报错
    return gameConfigSummary([]);
  }
}

/** 销毁当前所有文档对应的 Monaco model。 */
function disposeAllModels(): void {
  for (const doc of useAppStore.getState().documents) {
    disposeModel(doc.path);
  }
}

/** 验证并打开一个 WebGAL 项目目录。 */
export async function openProject(path: string): Promise<void> {
  const gameConfig = await fs.exists(joinPath(path, 'game', 'config.txt'));
  const indexHtml = await fs.exists(joinPath(path, 'index.html'));
  const hasGameConfig = gameConfig.exists && !gameConfig.isDirectory;
  const hasIndexHtml = indexHtml.exists && !indexHtml.isDirectory;

  if (!hasGameConfig && !hasIndexHtml) {
    throw new Error('不是有效的 WebGAL 项目 (缺少 game/config.txt 或 index.html)');
  }

  await lspClient.start();

  const store = useAppStore.getState();
  const prev = store.projectPath;
  if (prev && prev !== path) {
    lspClient.changeWorkspaceFolders([path], [prev]);
  } else if (!prev) {
    lspClient.changeWorkspaceFolders([path], []);
  }

  // 关闭旧项目的所有文档与 model
  disposeAllModels();
  disposeAllNovelTabs();
  voiceController.resetProject();
  // 项目名取自 config.txt 的 Game_name; 读不到时 setProject 会退回目录名
  const summary = await readProjectConfigSummary(path);
  store.setProject(path, summary.name);
  store.updateSettings({
    recentProjects: upsertRecentProject(store.settings.recentProjects, path, {
      name: summary.name || undefined,
      description: summary.description || undefined,
      titleImg: summary.titleImg || undefined,
    }),
  });
  previewClient.resetSite();

  // 恢复上次打开的场景选项卡 (文件还在才恢复; 单个文件打不开就跳过)
  await restoreSession(path);
}

/**
 * 恢复某项目上次打开的场景选项卡。
 *
 * 恢复的是**路径**而不是内容: 磁盘上那份才是最新的。已经被删掉的文件直接跳过 ——
 * 一个早已不存在的文件不该让整个恢复过程失败。
 */
export async function restoreSession(projectPath: string): Promise<void> {
  const session = loadSession(projectPath);
  if (!session || session.tabs.length === 0) return;

  for (const tabPath of session.tabs) {
    const exists = await fs.exists(tabPath);
    if (!exists.exists || exists.isDirectory) continue;
    try {
      await openFile(tabPath);
    } catch {
      // 读不出来 (编码/权限) 就跳过这一个
    }
  }

  const active = session.activeTab;
  if (!active) return;
  const store = useAppStore.getState();
  const activeId = sceneTabId(active);
  if (store.tabs.some((tab) => tab.id === activeId)) store.activateTab(activeId);
}

let sessionTrackingStarted = false;

/**
 * 开始跟踪选项卡变化并写入本地 (应用启动时调一次)。
 *
 * 用订阅而不是"关闭项目时保存": 应用可能是直接关窗口退出的, 那时没有任何关闭回调 ——
 * 只有持续保存才拿得到最后的状态。
 */
export function startSessionTracking(): void {
  if (sessionTrackingStarted) return;
  sessionTrackingStarted = true;
  useAppStore.subscribe((state, previous) => {
    if (!state.projectPath) return;
    if (state.tabs === previous.tabs && state.activeTabId === previous.activeTabId) return;
    saveSession(state.projectPath, sessionFromTabs(state.tabs, state.activeTabId));
  });
}

/** 关闭当前项目。 */
export function closeProject(): void {
  const store = useAppStore.getState();
  if (store.projectPath) {
    lspClient.changeWorkspaceFolders([], [store.projectPath]);
  }
  disposeAllModels();
  disposeAllNovelTabs();
  voiceController.resetProject();
  store.setProject(null);
  previewClient.resetSite();
}

// -------- 新建项目 --------

export interface CreateProjectInput {
  /** 用户填写的项目名称 (同时写入 `Game_name`) */
  name: string;
  /** 项目存放的父目录 */
  directory: string;
  /** 作为项目骨架的引擎 (整份复制) */
  engine: EngineEntry | null;
  /** 可选的模板 (复制到 game/template, 覆盖引擎内置模板) */
  template: TemplateEntry | null;
}

/**
 * 由引擎 (+ 可选模板) 生成一个新项目。
 *
 * WebGAL 的"项目"就是一份引擎发行包 (静态站点) 加上 `game/` 里的内容, 因此建项目 =
 * 整份复制引擎目录, 再按需覆盖模板, 最后写死这一份游戏自己的 `Game_name` 与 `Game_key`
 * (`Game_key` 决定存档隔离, 不写的话所有新项目会共用引擎自带的存档).
 *
 * 复制过程没有进度回调, 大引擎会安静几十秒 —— 调用方负责显示"正在复制"。
 */
export async function createProject(input: CreateProjectInput): Promise<string> {
  const name = input.name.trim();
  if (!name) throw new Error('请填写项目名称');
  if (!input.engine) throw new Error('请先在设置中添加 WebGAL 引擎');

  const directory = stripTrailingSeparator(input.directory);
  if (!directory) throw new Error('请选择项目存放位置');

  const target = joinPath(directory, sanitizeFolderName(name));
  if ((await fs.exists(target)).exists) {
    throw new Error(`目标目录已存在: ${target}`);
  }

  await fs.mkdir(target);
  try {
    await copyDirectory(input.engine.path, target);
    if (input.template) await applyTemplateToProject(target, input.template.path);
    await writeInitialGameConfig(target, name);
  } catch (error) {
    // 半成品目录必须清掉: 否则用户重试时会卡在"目标目录已存在"
    await fs.remove(target, true).catch(() => {});
    throw error;
  }

  const store = useAppStore.getState();
  store.setProjectBinding(target, { engineId: input.engine.id, templateId: input.template?.id });
  return target;
}

/** 写入新项目的初始配置 (名称 + 识别码); 引擎自带的 config.txt 会被就地改写。 */
async function writeInitialGameConfig(projectPath: string, name: string): Promise<void> {
  const configPath = configPathOf(projectPath);
  const exists = (await fs.exists(configPath)).exists;
  const text = exists ? await fs.readTextLossy(configPath) : '';
  await fs.writeText(configPath, setGameConfigValues(text, { Game_name: name, Game_key: crypto.randomUUID() }));
}

// -------- 模板 / 引擎切换 --------

/** 将模板目录复制到项目 game/template (替换原有内容)。 */
export async function applyTemplateToProject(projectPath: string, templatePath: string): Promise<void> {
  const target = joinPath(projectPath, 'game', 'template');
  await fs.remove(target, true).catch(() => {});
  await copyDirectory(templatePath, target);
}

/** 切换当前项目的模板, 并刷新预览 (整体重挂 iframe, 兼容旧版引擎)。 */
export async function switchTemplate(templateId: string | null, templatePath: string | null): Promise<void> {
  const store = useAppStore.getState();
  const projectPath = store.projectPath;
  if (!projectPath) return;

  if (templatePath) {
    await applyTemplateToProject(projectPath, templatePath);
  } else {
    await fs.remove(joinPath(projectPath, 'game', 'template'), true).catch(() => {});
  }

  // 只改模板: 引擎绑定必须原样保留, 否则切换模板会把项目用的引擎一并抹掉
  const previous = findBinding(store.projectBindings, projectPath);
  store.setProjectBinding(projectPath, { ...previous, templateId: templateId ?? undefined });

  // 通知引擎重拉模板 (新版 V1 引擎支持时无需重启即可生效)
  await previewClient.reloadTemplates();

  // 无论引擎版本, 均强制整体刷新预览 iframe, 保证模板立即生效
  // (旧版引擎对 reload-templates 支持不一致 / 经 service worker 缓存, 必须重挂)
  store.requestPreviewReload();
}

/**
 * 切换当前项目使用的引擎, 并重挂预览。
 *
 * `engineId` 为 null 表示"项目自带": 不挂任何引擎层, 直接跑项目目录里的 index.html。
 */
export async function switchProjectEngine(engineId: string | null): Promise<void> {
  const store = useAppStore.getState();
  const projectPath = store.projectPath;
  if (!projectPath) return;

  const previous = findBinding(store.projectBindings, projectPath);
  store.setProjectBinding(projectPath, { ...previous, engineId: engineId ?? undefined });
  // 站点是按"项目 + 引擎"注册的, 缓存里那份还挂着旧引擎, 必须作废重注册
  previewClient.resetSite();
  store.requestPreviewReload();
}
